CREATE SEQUENCE order_number_seq START WITH 1000 INCREMENT BY 5 MAXVALUE 999999999 CYCLE CACHE 20;

-- customers
CREATE TABLE customers (
    id number(19) GENERATED ALWAYS AS IDENTITY (START WITH 100 INCREMENT BY 2) NOT NULL,
    code char(10 char) NOT NULL,
    name varchar2(150 char) NOT NULL,
    email varchar2(200 char) NULL,
    remarks clob NULL,
    balance number(10,2) DEFAULT 10 NOT NULL,
    status varchar2(1 char) DEFAULT 'A' NOT NULL,
    created_at timestamp(6) DEFAULT CURRENT_TIMESTAMP NOT NULL,
    balance_twice number(14,2) GENERATED ALWAYS AS (balance * 2) VIRTUAL,
    vip number(1) DEFAULT 0 NOT NULL,
    CONSTRAINT pk_customers PRIMARY KEY (id),
    CONSTRAINT ck_customers_balance CHECK (balance >= -100)
);
CREATE INDEX ix_customers_name ON customers (name, created_at DESC);
CREATE UNIQUE INDEX ix_customers_code_lookup ON customers (code);
CREATE INDEX ix_customers_email_lower ON customers ((lower(email)));
COMMENT ON TABLE customers IS 'Customers who place orders, with their balance.';
COMMENT ON COLUMN customers.remarks IS 'Remarks about the customer.';

-- orders
CREATE TABLE orders (
    id number(19) DEFAULT order_number_seq.NEXTVAL NOT NULL,
    "number" varchar2(16 char) NOT NULL,
    customer_id number(19) NOT NULL,
    total number(12,2) DEFAULT 0 NOT NULL,
    placed_on date NULL,
    CONSTRAINT pk_orders_id PRIMARY KEY (id),
    CONSTRAINT uq_orders_customer_number UNIQUE (customer_id, "number"),
    CONSTRAINT fk_orders_customer FOREIGN KEY (customer_id) REFERENCES customers (id) DEFERRABLE INITIALLY IMMEDIATE,
    CONSTRAINT ck_orders_total CHECK (total >= 0)
);

-- order_items
CREATE TABLE order_items (
    order_id number(19) NOT NULL,
    line_no number(10) GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    sku char(20 char) NOT NULL,
    quantity number(19) NOT NULL,
    CONSTRAINT pk_order_lines PRIMARY KEY (order_id, line_no),
    CONSTRAINT fk_order_lines_order FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE,
    CONSTRAINT ck_order_lines_quantity CHECK (quantity > 0)
);
CREATE INDEX ix_order_lines_product ON order_items (sku);
